"% Trim analysis: steady climbing coordinated turn
% Three coupled nonlinear equations in unknowns (alpha, T, delta_e)
% Solved by Newton-Raphson iteration

% Aircraft parameters
W   = 230000.0;      % lbf, weight
S   = 2400.0;        % ft^2, wing area
h   = 31000.0;       % ft, altitude
V   = 730.0;         % ft/s, true airspeed
gamma_deg = 3.0;     % deg, climb angle
phi_deg   = 30.0;    % deg, bank angle

% Lift coefficients
CL0  = 0.15;
CLa  = 5.2;          % per rad
CLde = 0.35;         % per rad

% Drag (parabolic)
CD0 = 0.021;
k   = 0.043;

% Pitching moment about CG
Cm0        = 0.02;
Cmalpha    = -0.3;   % per rad
Cmdelta_e  = -0.85;  % per rad
cbar       = 17.0;   % ft, mean aerodynamic chord

% Atmosphere (exponential)
rho0    = 0.0023769;     % slug/ft^3
h_scale = 23800.0;       % ft
rho     = rho0 * exp(-h/h_scale);
q       = 0.5 * rho * V^2;   % dynamic pressure, lbf/ft^2

% Thrust installation
i_T_deg = 2.5;       % deg, thrust line pitch vs body axis
z_T     = 2.0;       % ft, perpendicular arm from CG

% Angles in radians
gamma = gamma_deg * pi/180;
phi   = phi_deg   * pi/180;
i_T   = i_T_deg   * pi/180;

% Initial guess (within physical range)
x = [5.0*pi/180; 30000.0; -1.0*pi/180];   % [alpha; T; delta_e]

% Newton-Raphson iteration
max_iter = 100;
tol      = 1e-10;
converged = false;

for iter = 1:max_iter
    a  = x(1);
    Tv = x(2);
    de = x(3);

    % Aerodynamic functions
    CL = CL0 + CLa*a + CLde*de;
    CD = CD0 + k*CL^2;

    % Three coupled equilibrium residuals
    F1 = q*S*CL*cos(phi) + Tv*sin(a + i_T) - W*cos(gamma);
    F2 = Tv*cos(a + i_T) - q*S*CD - W*sin(gamma);
    F3 = q*S*cbar*(Cm0 + Cmalpha*a + Cmdelta_e*de) + Tv*sin(i_T)*z_T;
    F  = [F1; F2; F3];

    if norm(F) < tol
        converged = true;
        break;
    end

    % Jacobian dF/dx
    J = zeros(3,3);
    J(1,1) = q*S*CLa*cos(phi) + Tv*cos(a + i_T);
    J(1,2) = sin(a + i_T);
    J(1,3) = q*S*CLde*cos(phi);

    J(2,1) = -Tv*sin(a + i_T) - q*S*2*k*CL*CLa;
    J(2,2) = cos(a + i_T);
    J(2,3) = -q*S*2*k*CL*CLde;

    J(3,1) = q*S*cbar*Cmalpha;
    J(3,2) = sin(i_T)*z_T;
    J(3,3) = q*S*cbar*Cmdelta_e;

    % Newton step
    dx = -J\F;

    % Damped step to keep variables in physical range
    step = 1.0;
    x_trial = x + step*dx;
    for kk = 1:30
        if (x_trial(1) > 0 && x_trial(1) < 0.35) && ...
           (x_trial(2) > 100 && x_trial(2) < 500000) && ...
           (x_trial(3) > -0.6 && x_trial(3) < 0.6)
            break;
        end
        step  = step * 0.5;
        x_trial = x + step*dx;
    end
    x = x_trial;
end

% Extract trim solution
alpha_trim_deg   = x(1) * 180/pi;
delta_e_trim_deg = x(3) * 180/pi;
thrust_lbf       = x(2);
load_factor      = cos(gamma)/cos(phi);

% Build result struct
result = struct( ...
    'alpha_trim_deg',   alpha_trim_deg, ...
    'thrust_lbf',       thrust_lbf, ...
    'delta_e_trim_deg', delta_e_trim_deg, ...
    'load_factor',      load_factor );

% Write JSON to current working directory
json_text = jsonencode(result);
fid = fopen('result.json','w');
fwrite(fid, json_text);
fclose(fid);"
